        paidMinutes,
        normalMinutes,
        overtime50Minutes,
        overtime100Minutes,
        eveningMinutes,
        nightMinutes,
        sundayMinutes,
        normalPay,
        overtime50Pay,
        overtime100Pay,
        eveningPay,
        nightPay,
        sundayPay,
